def f():
    try:
        raise ValueError("x")
    except:
        return "caught"

def f():
    try:
        raise RuntimeError("x")
    except ValueError:
        return "value"
    except:
        return "bare"

def f():
    try:
        raise ValueError("x")
    except:
        raise

def f():
    try:
        value = 1
    except ValueError:
        value = 2
    else:
        value = 3
    return value

def f():
    try:
        raise ValueError("x")
    except ValueError:
        value = 2
    else:
        value = 3
    return value

def f():
    try:
        value = 1
    except ValueError:
        value = 2
    else:
        value = 3
    finally:
        value = 4
    return value

def f():
    try:
        raise KeyError("x")
    except (ValueError, KeyError) as error:
        return error
